    totals = {}
    for name, weight in load.items():
        if weight <= 0:
            continue
        for step in paths[name]:
            totals[step] = totals.get(step, 0) + weight
    for name, total in totals.items():
        bound = total if total < ceiling else ceiling
        if nodes[name]['capacity'] < bound:
            return False
    return True'''
